package backupstore

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/url"
	"sort"
	"strings"
	"time"
)

// unsignedPayload is the payload hash S3 accepts when the body is streamed
// instead of buffered. AWS requires HTTPS for it, which is how S3 endpoints are
// configured in practice.
const unsignedPayload = "UNSIGNED-PAYLOAD"

// sigv4 signs requests with AWS signature version 4. It is verified against
// vectors generated by botocore (see sigv4_test.go).
type sigv4 struct {
	accessKey    string
	secretKey    string
	sessionToken string
	region       string
	service      string
}

// sign adds the SigV4 headers to a request. payloadHash must be the hex sha256
// of the body or unsignedPayload for a streamed body. An x-amz-date header that
// is already present is honoured, so callers (and tests) can pin the clock.
func (a sigv4) sign(req *http.Request, payloadHash string) {
	amzDate := req.Header.Get("x-amz-date")
	if amzDate == "" {
		amzDate = time.Now().UTC().Format("20060102T150405Z")
		req.Header.Set("x-amz-date", amzDate)
	}
	shortDate := amzDate
	if len(amzDate) >= 8 {
		shortDate = amzDate[:8]
	}
	req.Header.Set("x-amz-content-sha256", payloadHash)
	if a.sessionToken != "" {
		req.Header.Set("x-amz-security-token", a.sessionToken)
	}
	if req.Host == "" {
		req.Host = req.URL.Host
	}

	canonicalHeaders, signedHeaders := canonicalHeadersOf(req)
	canonicalRequest := strings.Join([]string{
		req.Method,
		canonicalURI(req.URL),
		canonicalQuery(req.URL),
		canonicalHeaders,
		signedHeaders,
		payloadHash,
	}, "\n")

	scope := strings.Join([]string{shortDate, a.region, a.service, "aws4_request"}, "/")
	stringToSign := strings.Join([]string{
		"AWS4-HMAC-SHA256",
		amzDate,
		scope,
		hex.EncodeToString(sha256Sum([]byte(canonicalRequest))),
	}, "\n")

	signature := hex.EncodeToString(hmacSHA256(a.signingKey(shortDate), stringToSign))
	req.Header.Set("Authorization", fmt.Sprintf(
		"AWS4-HMAC-SHA256 Credential=%s/%s, SignedHeaders=%s, Signature=%s",
		a.accessKey, scope, signedHeaders, signature))
}

// signingKey derives the per-day signing key.
func (a sigv4) signingKey(shortDate string) []byte {
	date := hmacSHA256([]byte("AWS4"+a.secretKey), shortDate)
	region := hmacSHA256(date, a.region)
	service := hmacSHA256(region, a.service)
	return hmacSHA256(service, "aws4_request")
}

func hmacSHA256(key []byte, data string) []byte {
	mac := hmac.New(sha256.New, key)
	mac.Write([]byte(data))
	return mac.Sum(nil)
}

func sha256Sum(data []byte) []byte {
	sum := sha256.Sum256(data)
	return sum[:]
}

// payloadHashOf returns the hex sha256 of a buffered payload.
func payloadHashOf(data []byte) string {
	return hex.EncodeToString(sha256Sum(data))
}

// canonicalHeadersOf renders the signed headers and their list.
func canonicalHeadersOf(req *http.Request) (string, string) {
	names := []string{}
	values := map[string]string{}
	add := func(name, value string) {
		name = strings.ToLower(name)
		if _, seen := values[name]; !seen {
			names = append(names, name)
		}
		values[name] = strings.Join(strings.Fields(value), " ")
	}
	add("host", req.Host)
	if v := req.Header.Get("Content-Type"); v != "" {
		add("content-type", v)
	}
	for name, vals := range req.Header {
		lower := strings.ToLower(name)
		if strings.HasPrefix(lower, "x-amz-") {
			add(lower, strings.Join(vals, ","))
		}
	}
	sort.Strings(names)
	var b strings.Builder
	for _, name := range names {
		b.WriteString(name)
		b.WriteString(":")
		b.WriteString(values[name])
		b.WriteString("\n")
	}
	return b.String(), strings.Join(names, ";")
}

// canonicalURI renders the path the way SigV4 expects it: every segment
// percent-encoded, slashes kept.
func canonicalURI(u *url.URL) string {
	if u.Path == "" {
		return "/"
	}
	segments := strings.Split(u.Path, "/")
	for i, seg := range segments {
		segments[i] = awsEncode(seg, true)
	}
	out := strings.Join(segments, "/")
	if !strings.HasPrefix(out, "/") {
		out = "/" + out
	}
	return out
}

// canonicalQuery renders the sorted, encoded query string.
func canonicalQuery(u *url.URL) string {
	if u.RawQuery == "" {
		return ""
	}
	values, err := url.ParseQuery(u.RawQuery)
	if err != nil {
		return encodeQuery(u.Query())
	}
	return encodeQuery(values)
}

// encodeQuery sorts and encodes query values the SigV4 way.
func encodeQuery(values url.Values) string {
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	parts := []string{}
	for _, key := range keys {
		vals := append([]string(nil), values[key]...)
		sort.Strings(vals)
		if len(vals) == 0 {
			parts = append(parts, awsEncode(key, true)+"=")
			continue
		}
		for _, value := range vals {
			parts = append(parts, awsEncode(key, true)+"="+awsEncode(value, true))
		}
	}
	return strings.Join(parts, "&")
}

// awsEncode percent-encodes like AWS expects it (RFC 3986, uppercase hex).
// Slashes are only encoded when encodeSlash is true.
func awsEncode(value string, encodeSlash bool) string {
	var b strings.Builder
	for i := 0; i < len(value); i++ {
		c := value[i]
		switch {
		case c >= 'A' && c <= 'Z', c >= 'a' && c <= 'z', c >= '0' && c <= '9',
			c == '-', c == '_', c == '.', c == '~':
			b.WriteByte(c)
		case c == '/' && !encodeSlash:
			b.WriteByte(c)
		default:
			fmt.Fprintf(&b, "%%%02X", c)
		}
	}
	return b.String()
}
